INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Läuft eine While-Schleife immer unendlich?', 2, '[{"text": "Nein", "correct": true, "because": "Abbruchbedingung steuert"}, {"text": "Ja", "correct": false, "because": "Bedingung kann enden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer While-Schleife?', 3, '[{"text": "Wiederholung bei Bedingung", "correct": true, "because": "Läuft, solange wahr"}, {"text": "Einmalige Ausführung", "correct": false, "because": "Für If geeignet"}, {"text": "UI-Anpassung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente steuern eine While-Schleife?', 5, '[{"text": "Bedingung", "correct": true, "because": "Bestimmt Ausführung"}, {"text": "Abbruchmechanismus", "correct": true, "because": "Beendet Schleife"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Datenbankzugriff", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) While prüft die Bedingung zuerst. b) Sie läuft ohne Bedingung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Bedingung nötig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer While-Schleife?', 4, '[{"text": "Bedingungsprüfung", "correct": false, "because": "Steuert Schleife"}, {"text": "Abbruchlogik", "correct": false, "because": "Verhindert Endlosschleife"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob While immer einen Zähler braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Bedingung reicht"}, {"text": "Ja", "correct": false, "because": "Für For typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um eine Schleife abzubrechen?', 3, '[{"text": "break", "correct": true, "because": "Sofortiger Abbruch"}, {"text": "continue", "correct": false, "because": "Nur Iteration überspringen"}, {"text": "return", "correct": false, "because": "Funktion beenden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einer While-Schleife entscheidend?', 5, '[{"text": "Klare Bedingung", "correct": true, "because": "Steuert Ausführung"}, {"text": "Abbruchmöglichkeit", "correct": true, "because": "Vermeidet Endlosschleife"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) While ist flexibler als For. b) Sie ist immer langsamer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Nutzung ab"}, {"text": "Beides stimmt", "correct": false, "because": "Performance variiert"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine While-Schleife?', 4, '[{"text": "Bedingung", "correct": false, "because": "Steuert Schleife"}, {"text": "Codeblock", "correct": false, "because": "Definiert Aktion"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Prüft While die Bedingung nach jedem Durchlauf?', 2, '[{"text": "Nein", "correct": true, "because": "Vor jedem Durchlauf"}, {"text": "Ja", "correct": false, "because": "Do-While tut das"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine While-Schleife?', 4, '[{"text": "Flexibilität", "correct": true, "because": "Bedingung frei wählbar"}, {"text": "Kontrolle", "correct": true, "because": "Abbruch anpassbar"}, {"text": "Datenkompression", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass While nur für einfache Aufgaben ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch komplex nutzbar"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer While-Schleife?', 3, '[{"text": "Klarer Abbruch", "correct": true, "because": "Vermeidet Endlosschleife"}, {"text": "Schnelle Definition", "correct": false, "because": "Korrektheit zählt"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) While kann leer laufen. b) Sie braucht immer break.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist optional"}, {"text": "Beides stimmt", "correct": false, "because": "break nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei einer While-Schleife?', 5, '[{"text": "Endlosschleife", "correct": true, "because": "Falsche Bedingung"}, {"text": "Ressourcenverbrauch", "correct": true, "because": "Lange Laufzeit"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Schleife unwichtig?', 3, '[{"text": "Bedingungslogik", "correct": false, "because": "Steuert Ablauf"}, {"text": "Abbruchkriterium", "correct": false, "because": "Beendet Schleife"}, {"text": "Serverdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich eine While-Schleife ohne Abbruch nutzen?', 3, '[{"text": "Ja", "correct": true, "because": "Möglich, aber riskant"}, {"text": "Nein", "correct": false, "because": "Technisch machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob While auch nach der Schleife prüft?', 2, '[{"text": "Nein", "correct": true, "because": "Nur vorher, anders bei Do-While"}, {"text": "Ja", "correct": false, "because": "Verwechselbar mit Do-While"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um die aktuelle Iteration zu überspringen?', 4, '[{"text": "continue", "correct": true, "because": "Springt zur nächsten"}, {"text": "break", "correct": false, "because": "Beendet Schleife"}, {"text": "exit", "correct": false, "because": "Programmende"}]');
